 editAlmanac(e){const el=e.target,key=el.dataset.almanacKey,kind=this._settingsTab;if(!key||!['citations','dictons'].includes(kind)||!this._almanacEditors?.[kind]||this._almanacSaving)return;const model=this._almanacEditors[kind];if(kind==='citations')model.entries[key][el.dataset.almanacField]=el.value;else model.entries[key]=el.value;this._almanacStatus[kind]=this.t('almanac_unsaved');const status=this.shadowRoot.querySelector('.almanac-status');if(status)status.textContent=this._almanacStatus[kind];}
 async reloadAlmanac(){if(this._almanacSaving)return;const kind=this._settingsTab;try{const data=await this.hass.callWS({type:'station_meteo/almanac'});if(!this.draft)return;this._almanacEditors??={};this._almanacEditors[kind]=structuredClone(data[kind]);this._almanacStatus[kind]='';}catch{this._almanacStatus[kind]=this.t('almanac_editor_unavailable');}if(this.draft)this.renderSettings();}
